INSERT INTO duas (id, category, keywords, arabic, transliteration, translation_en, translation_ur, reference, verified)
VALUES
    ('sleep', 'Before Sleeping · Sone Se Pehle Ki Dua', ARRAY['sleep', 'sona', 'sote', 'bed', 'neend', 'sony', 'sone', 'soney', 'sone se pehle'], 'بِاسْمِكَ اللّهُمَّ أَمُوتُ وَأَحْيَا', 'Bismika Allahumma amutu wa ahya', 'In Your name, O Allah, I die and I live.', 'Aey Allah, tere hi naam ke sath main marta hoon aur tere hi naam ke sath jeeta hoon (yani sota aur jagta hoon).', 'Sahih al-Bukhari 6324', FALSE),
    ('waking-up', 'After Waking Up · Neend Se Jagny Ki Dua', ARRAY['wake up', 'jagna', 'jagny', 'morning wake', 'uthna', 'neend se bedar', 'bedaar', 'neend se jagny', 'neend se jagna'], 'الْحَمْدُ لِلّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ', 'Alhamdu lillahil-ladhi ahyana ba''da ma amatana wa ilayhin-nushur', 'All praise is for Allah who gave us life after having taken it from us, and unto Him is the resurrection.', 'Tamam tareefein Allah ke liye hain jisne humein maut (neend) ke baad zindagi ata ki, aur usi ki taraf dobara uthna hai.', 'Sahih al-Bukhari 6312', FALSE),
    ('before-eating', 'Before Eating · Khany Se Pehle Ki Dua', ARRAY['eating', 'khana', 'khaty', 'food', 'meal', 'khany se pehle', 'khany sy phly', 'khana khany se pehle'], 'بِسْمِ اللّهِ', 'Bismillah. (If you forget at the start: Bismillahi awwalahu wa akhirahu)', 'In the name of Allah. If you forget at the beginning, say: "In the name of Allah at the beginning and at the end of it."', 'Allah ke naam se (shuru karta hoon). Agar shuru mein bhool jaye to kahe: "Bismillahi awwalahu wa akhirahu" (shuru mein bhi aur aakhir mein bhi Allah ke naam se).', 'Sunan Abi Dawud 3767', FALSE),
    ('after-eating', 'After Eating · Khany Ke Baad Ki Dua', ARRAY['after eating', 'khany k baad', 'finish meal', 'khany ke baad', 'khane ke baad'], 'الْحَمْدُ لِلّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ', 'Alhamdu lillahil-ladhi at''amani hadha wa razaqanihi min ghayri hawlim minni wa la quwwah', 'All praise is for Allah who fed me this and provided it for me without any might or power on my part.', 'Tamam tareefein Allah ke liye hain jisne mujhe ye khana khilaya aur bina meri kisi taqat ya koshish ke mujhe rizq diya.', 'Sunan Abi Dawud 4023', FALSE),
    ('leaving-home', 'Leaving Home · Ghar Se Nikalny Ki Dua', ARRAY['leaving home', 'ghar sy niklna', 'going out', 'bahir jana', 'ghar se nikalne', 'niklny', 'ghar se nikalny', 'ghar se nikalna'], 'بِسْمِ اللّهِ تَوَكَّلْتُ عَلَى اللّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّهِ', 'Bismillahi tawakkaltu ''alallahi wa la hawla wa la quwwata illa billah', 'In the name of Allah, I place my trust in Allah, and there is no might nor power except with Allah.', 'Allah ke naam se (ghar se nikalta hoon), maine Allah par bharosa kiya, aur koi taqat ya qudrat nahi magar Allah ke sath.', 'Sunan Abi Dawud 5095', FALSE),
    ('distress', 'During Distress · Pareshani Ke Waqt Ki Dua', ARRAY['distress', 'pareshan', 'worried', 'anxiety', 'ghum', 'sad', 'stress'], 'لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَالأَرْضِ، رَبُّ الْعَرْشِ الْعَظِيمِ', 'La ilaha illal-lahu Al-`Azim, al-Halim, La ilaha illal-lahu Rabbu-s-samawati wal-ard wa Rabbu-l-arsh il-azim', 'There is no deity but Allah, the Magnificent, the Forbearing. There is no deity but Allah, Lord of the heavens and the earth, Lord of the Mighty Throne.', 'Allah ke siwa koi ibadat ke laiq nahi, jo bohot bara aur bardbaar hai. Allah ke siwa koi ibadat ke laiq nahi jo aasmanon aur zameen ka Rab hai, jo Arsh-e-Azeem ka Rab hai.', 'Sahih al-Bukhari 6345', FALSE),
    ('forgiveness', 'Seeking Forgiveness · Maafi Mangny Ki Dua', ARRAY['forgiveness', 'maafi', 'gunah', 'astaghfirullah', 'sin', 'repent'], 'أَسْتَغْفِرُ اللّهَ الَّذِي لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ', 'Astaghfirullahil-ladhi la ilaha illa huwal-Hayyul-Qayyumu wa atubu ilayh', 'I seek the forgiveness of Allah, besides whom there is no deity, the Ever-Living, the Sustainer of existence, and I repent unto Him.', 'Main us Allah se maafi mangta hoon jiske siwa koi ibadat ke laiq nahi, jo zinda aur hamesha qaim rehny wala hai, aur main uski taraf tauba karta hoon.', 'Sunan Abi Dawud 1517', FALSE),
    ('travel', 'During Travel · Safar/Sawari Par Baithny Ki Dua', ARRAY['travel', 'safar', 'journey', 'safar par', 'sawari'], 'سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَىٰ رَبِّنَا لَمُنْقَلِبُونَ', 'Subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila rabbina lamunqalibun', 'Glory to Him who has subjected this to us, and we could never have accomplished this by ourselves, and to our Lord we will surely return.', 'Pak hai wo Zaat jisne is (sawari) ko humare qabu mein diya, warna hum khud isay qabu mein nahi la sakte thay, aur beshak hum apne Rab ki taraf lautny wale hain.', 'Sahih Muslim 1342, Quran 43:13-14', FALSE),
    ('entering-masjid', 'Entering Masjid · Masjid Mein Dakhil Hony Ki Dua', ARRAY['masjid', 'mosque', 'entering mosque', 'masjid mein dakhil'], 'اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ', 'Allahumma-ftah li abwaba rahmatik', 'O Allah! open for me the doors of Thy mercy', 'Aey Allah, mere liye apni rehmat ke darwaze khol de.', 'Sahih Muslim 713', FALSE)
ON CONFLICT (id) DO UPDATE SET
    category = EXCLUDED.category,
    keywords = EXCLUDED.keywords,
    arabic = EXCLUDED.arabic,
    transliteration = EXCLUDED.transliteration,
